/**
 * @method
 * @name scwin.tx_fn_existYn_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_existYn_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_existYn_xhr", unresolved: "action:self_submit:tx_fn_existYn_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.existYn
 * @author Inswave
 * @date 2026. 09. 29
 * @param comNm advceComIsurCd advceComApplTpCd
 * @returns
 * @hidden N
*/
scwin.existYn = async function (comNm, advceComIsurCd, advceComApplTpCd) {
    /* sdd-asis-lifecycle:begin fn_existYn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var advceComApplTpCd = advceComApplTpCd;
    (document.searchForm || { elements: [] }).action = "/account/advceComInfo.do";
    $c.util.getComponent('dma_applicationReq').set('method', "chkAdvceCom");
    $c.util.getComponent("dma_applicationReq").set("advceComIsurCd", advceComIsurCd);
    $c.util.getComponent("dma_applicationReq").set("advceComApplTpCd", advceComApplTpCd);
    let result = await scwin.tx_fn_existYn_xhr();
    result = scwin.trim(result);
    let processYn = false;
    let msg = "";
    if (result === "addAppl") {
        msg = "『" + comNm + "』코넥스 법인은  이미 [추가] 신청하셨습니다.";
    } else {
        if (result === "addOk") {
            msg = "『" + comNm + "』코넥스 법인을 자문기업으로 [추가] 신청하시겠습니까?";
        } else {
            if (result === "addNot") {
                msg = "[추가] 신청하신 『" + comNm + "』코넥스 법인은 현재 자문기업으로 등록되어 있습니다.";
            } else {
                if (result === "exceptAppl") {
                    msg = "『" + comNm + "』코넥스 법인은  이미 [제외] 신청하셨습니다.";
                } else {
                    if (result === "exceptOk") {
                        msg = "『" + comNm + "』코넥스 법인을 자문기업에서 [제외] 신청하시겠습니까?";
                    } else {
                        if (result === "exceptNot") {
                            msg = "[제외] 신청하신 『" + comNm + "』코넥스 법인은 현재 등록된 자문기업이 아닙니다.";
                        }
                    }
                }
            }
        }
    }
    if (result === "addOk" || result === "exceptOk") {
        if (await $c.win.confirm(msg)) {
            processYn = true;
        }
    } else {
        await $c.win.alert(msg);
    }
    return processYn;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.disabled
 * @author Inswave
 * @date 2026. 09. 29
 * @param advceComApplTpCd
 * @returns
 * @hidden N
*/
scwin.disabled = function (advceComApplTpCd) {
    /* sdd-asis-lifecycle:begin fn_disabled — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (advceComApplTpCd === 'A') {
        $c.util.getComponent('cal_contrtDd').setStyle("background-color", "#FFFFFF");
        $c.util.getComponent("cal_releasDd").setValue("");
        $c.util.getComponent('cal_releasDd').setStyle("background-color", "#F1F1F1");
    } else {
        if (advceComApplTpCd === 'E') {
            $c.util.getComponent('cal_releasDd').setStyle("background-color", "#FFFFFF");
            $c.util.getComponent("cal_contrtDd").setValue("");
            $c.util.getComponent('cal_contrtDd').setStyle("background-color", "#F1F1F1");
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.application
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.application = async function () {
    /* sdd-asis-lifecycle:begin fn_application — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.advceComApplInfoForm || { elements: [] });
    const comNm = $c.util.getComponent('ipt_comNm').getValue();
    const advceComIsurCd = $c.util.getComponent("dma_applicationReq").get("advceComIsurCd");
    let advceComApplTpCd = "";
    advceComApplTpCd = $c.util.getComponent("dma_applicationReq").get("advceComApplTpCd");
    if (!scwin.fn_IsChecked(frm.advceComApplTpCd)) {
        await $c.win.alert('신청구분을 선택하세요.');
        return;
    }
    if (await scwin.nullChk($c.util.fieldEl('cal_applReqDd', 'applReqDd'))) {
        return;
    }
    if (!await scwin.chkToday($c.util.fieldEl('cal_applReqDd', 'applReqDd'))) {
        return;
    }
    if (advceComApplTpCd === 'A') {
        if (await scwin.nullChk($c.util.fieldEl('cal_contrtDd', 'contrtDd'))) {
            return;
        }
        if (scwin.isNotNull($c.util.fieldEl('cal_releasDd', 'releasDd'))) {
            await $c.win.alert('[추가] 신청시에는 해제일을 입력하지 않습니다.');
            $c.util.getComponent("cal_releasDd").setValue("");
            return;
        }
    } else {
        if (advceComApplTpCd === 'E') {
            if (await scwin.nullChk($c.util.fieldEl('cal_releasDd', 'releasDd'))) {
                return;
            }
            if (!await scwin.chkToday($c.util.fieldEl('cal_releasDd', 'releasDd'))) {
                return;
            }
            if (scwin.isNotNull($c.util.fieldEl('cal_contrtDd', 'contrtDd'))) {
                await $c.win.alert('[제외] 신청시에는 계약일을 입력하지 않습니다.');
                $c.util.getComponent("cal_contrtDd").setValue("");
                return;
            }
        }
    }
    if (await scwin.nullChk($c.util.fieldEl('ipt_comNm', 'comNm'))) {
        return;
    }
    if (await scwin.existYn(comNm, advceComIsurCd, advceComApplTpCd)) {
        (document.advceComApplInfoForm || { elements: [] }).action = "/account/advceComInfo.do";
        $c.util.getComponent('dma_applicationReq').set('method', "advceComInfoApply");
        { const nr = await scwin.tx_fn_application(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil25710/jldfil25710.xml", { "method": "advceComInfoApply" }); } };
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.modify = async function () {
    /* sdd-asis-lifecycle:begin fn_modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const statVal = $c.util.getComponent("dma_applicationReq").get("advceComProcsStatNm");
    if (statVal === "미처리") {
        (document.advceComApplInfoForm || { elements: [] }).action = "/account/advceComInfo.do";
        $c.util.getComponent('dma_applicationReq').set('method', "advceComInfoApply");
        $c.util.getComponent('dma_applicationReq').set('modifyYn', "Y");
        { const nr = await scwin.tx_fn_modify(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil25710/jldfil25710.xml", { "method": "advceComInfoApply", "modifyYn": "Y" }); } };
    } else {
        await $c.win.alert("[미처리] 상태인 신청건만 수정이 가능합니다.");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.findCompany
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.findCompany = async function () {
    /* sdd-asis-lifecycle:begin fn_findCompany — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const corpSearchURL = '/jldfil00033/jldfil00033.xml';
    scwin.setCorpInfo_recv(await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(corpSearchURL), { id: "corpWin", scrollbars: false, resizable: false, width: "600", height: "570", type: "pageFramePopup" }, { method: "loadInitPage", marketType: "konexMkt" }));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.loadForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param seq advceComIsurCd comNm advceComApplTpCd applReqDd contrtDd releasDd advceComProcsStatNm
 * @returns
 * @hidden N
*/
scwin.loadForm = function (seq, advceComIsurCd, comNm, advceComApplTpCd, applReqDd, contrtDd, releasDd, advceComProcsStatNm) {
    /* sdd-asis-lifecycle:begin fn_LoadForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.advceComApplInfoForm || { elements: [] });
    const regexp = /-/g;
    const undashApplReqDd = applReqDd.replace(regexp, "");
    const undashContrtDd = contrtDd.replace(regexp, "");
    const undashReleasDd = releasDd.replace(regexp, "");
    const obj = form.advceComApplTpCd;
    $c.util.getComponent("dma_applicationReq").set("seq", seq);
    $c.util.getComponent("dma_applicationReq").set("advceComIsurCd", advceComIsurCd);
    $c.util.getComponent('ipt_comNm').setValue(comNm);
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].value === advceComApplTpCd) {
            obj[i].checked = true;
        }
    }
    scwin.disabled(advceComApplTpCd);
    $c.util.getComponent('cal_applReqDd').setValue(undashApplReqDd);
    $c.util.getComponent('cal_contrtDd').setValue(undashContrtDd);
    $c.util.getComponent('cal_releasDd').setValue(undashReleasDd);
    $c.util.getComponent("dma_applicationReq").set("advceComProcsStatNm", advceComProcsStatNm);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
