/**
 * @method
 * @name scwin.chkToday
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.chkToday = async function (obj) {
    /* sdd-asis-lifecycle:begin fn_chkToday — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    const today = new Date(); 

    const nowYear 	= today.getYear();
    let nowMonth 	= today.getMonth() + 1;
    let nowDate 	= today.getDate();	

    if(nowMonth < 10) {
        nowMonth	= "0" + nowMonth;
    }
    if(parseInt(nowDate) < 10) {
        nowDate	= "0" + nowDate;
    }

    const toDd 	= nowYear + '' + nowMonth + '' + nowDate;	

    if(parseInt(toDd) >= parseInt(obj.value)) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(obj) + " : 오늘 이후의 일자를 입력하세요.");
        return false;
    } 
    return true;


    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isNotNull
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.isNotNull = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_IsNotNull — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    if(scwin.trim(_obj.value) === ''){
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isNull
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj _msg
 * @returns
 * @hidden N
*/
scwin.isNull = async function (_obj, _msg) {
    /* sdd-asis-lifecycle:begin fn_IsNull — as-is 원문 본문(전환 이관 · 포팅 적용됨) */


    if(scwin.trim(_obj.value) === ''){
        await $c.win.alert("'" + _msg + "' 항목을 입력하세요");
        _obj.focus();
        return true;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};



